messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Low Poly Treadmill Animation</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #87CEEB; }
        canvas { display: block; }
    </style>
</head>
<body>
<script type="module">
    import * as THREE from './three.module.js';

    // --- Configuration ---
    const CYCLE_DURATION = 10; // seconds
    const PHASE_STILL = 2;
    const PHASE_WALK = 3;
    const PHASE_RUN = 3;

    // Colors
    const COLOR_SKIN = 0xffd1b3;
    const COLOR_SHIRT = 0xff4444;
    const COLOR_PANTS = 0x3355aa;
    const COLOR_GROUND = 0x333333;
    const COLOR_MARKING = 0xffffff;

    // --- Scene Setup ---
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x87CEEB);
    scene.fog = new THREE.Fog(0x87CEEB, 10, 50);

    const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
    camera.position.set(0, 1.5, 6); // Side-on view
    camera.lookAt(0, 0.8, 0);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    document.body.appendChild(renderer.domElement);

    // --- Lighting ---
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
    scene.add(ambientLight);

    const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
    dirLight.position.set(5, 10, 5);
    dirLight.castShadow = true;
    dirLight.shadow.mapSize.width = 1024;
    dirLight.shadow.mapSize.height = 1024;
    scene.add(dirLight);

    // --- Materials ---
    const matSkin = new THREE.MeshStandardMaterial({ color: COLOR_SKIN, flatShading: true });
    const matShirt = new THREE.MeshStandardMaterial({ color: COLOR_SHIRT, flatShading: true });
    const matPants = new THREE.MeshStandardMaterial({ color: COLOR_PANTS, flatShading: true });
    const matGround = new THREE.MeshStandardMaterial({ color: COLOR_GROUND, flatShading: true });
    const matMark = new THREE.MeshBasicMaterial({ color: COLOR_MARKING });

    // --- Geometry Helpers ---
    function createLimb(w, h, d, mat, x, y, z) {
        const geo = new THREE.BoxGeometry(w, h, d);
        // Shift geometry so pivot is at the top
        geo.translate(0, -h/2, 0); 
        const mesh = new THREE.Mesh(geo, mat);
        mesh.position.set(x, y, z);
        mesh.castShadow = true;
        return mesh;
    }

    // --- Character Construction ---
    const characterGroup = new THREE.Group();
    scene.add(characterGroup);

    // 1. Hips (Root of movement)
    const hips = new THREE.Group();
    hips.position.y = 1.0;
    characterGroup.add(hips);

    // Torso
    const torso = createLimb(0.4, 0.5, 0.25, matShirt, 0, 0.25, 0);
    torso.geometry.translate(0, 0, 0); // Reset translation for torso
    hips.add(torso);

    // Head
    const head = createLimb(0.25, 0.25, 0.25, matSkin, 0, 0.125, 0);
    head.position.y = 0.5; // Relative to hips
    hips.add(head);

    // Legs
    // Left Leg
    const leftUpperLeg = createLimb(0.15, 0.4, 0.15, matPants, -0.12, 0, 0);
    hips.add(leftUpperLeg);
    const leftLowerLeg = createLimb(0.12, 0.4, 0.12, matPants, 0, 0.4, 0);
    leftUpperLeg.add(leftLowerLeg);

    // Right Leg
    const rightUpperLeg = createLimb(0.15, 0.4, 0.15, matPants, 0.12, 0, 0);
    hips.add(rightUpperLeg);
    const rightLowerLeg = createLimb(0.12, 0.4, 0.12, matPants, 0, 0.4, 0);
    rightUpperLeg.add(rightLowerLeg);

    // Arms
    // Left Arm
    const leftUpperArm = createLimb(0.12, 0.35, 0.12, matShirt, -0.25, 0.4, 0);
    hips.add(leftUpperArm);
    const leftLowerArm = createLimb(0.1, 0.3, 0.1, matSkin, 0, 0.35, 0);
    leftUpperArm.add(leftLowerArm);

    // Right Arm
    const rightUpperArm = createLimb(0.12, 0.35, 0.12, matShirt, 0.25, 0.4, 0);
    hips.add(rightUpperArm);
    const rightLowerArm = createLimb(0.1, 0.3, 0.1, matSkin, 0, 0.35, 0);
    rightUpperArm.add(rightLowerArm);

    // --- Ground / Treadmill ---
    const groundGeo = new THREE.PlaneGeometry(20, 20);
    const ground = new THREE.Mesh(groundGeo, matGround);
    ground.rotation.x = -Math.PI / 2;
    ground.receiveShadow = true;
    scene.add(ground);

    // Treadmill markings to show movement
    const markingGroup = new THREE.Group();
    scene.add(markingGroup);
    for(let i = -10; i <= 10; i++) {
        const mark = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.01, 0.2), matMark);
        mark.position.set(0, 0.01, i * 1.5);
        markingGroup.add(mark);
    }

    // --- Animation Logic ---
    const clock = new THREE.Clock();

    // Helper to interpolate between states
    function lerp(start, end, t) {
        return start * (1 - t) + end * t;
    }

    function animate() {
        requestAnimationFrame(animate);

        const elapsedTime = clock.getElapsedTime();
        const cycleTime = elapsedTime % CYCLE_DURATION;

        // Determine Phase
        let phase = 'STILL';
        let phaseTime = 0; // Time spent in current phase (0 to duration)

        if (cycleTime < PHASE_STILL) {
            phase = 'STILL';
            phaseTime = cycleTime;
        } else if (cycleTime < PHASE_STILL + PHASE_WALK) {
            phase = 'WALK';
            phaseTime = cycleTime - PHASE_STILL;
        } else {
            phase = 'RUN';
            phaseTime = cycleTime - (PHASE_STILL + PHASE_WALK);
        }

        // --- Animation Parameters ---
        let legSpeed = 0;
        let legAmp = 0;
        let armAmp = 0;
        let bodyLean = 0;
        let bodyBob = 0;
        let groundSpeed = 0;

        // Transition smoothing (optional, but makes it look better)
        // For this request, we will stick to distinct states but smooth the sine waves.

        if (phase === 'STILL') {
            // Reset to default standing pose
            // Default standing: Legs straight, Arms down slightly bent
            hips.rotation.x = 0;
            hips.position.y = 1.0;

            // Reset limbs to T-pose-ish or A-pose
            leftUpperLeg.rotation.x = 0;
            rightUpperLeg.rotation.x = 0;
            leftLowerLeg.rotation.x = 0;
            rightLowerLeg.rotation.x = 0;

            leftUpperArm.rotation.x = 0.2; // Slight forward
            rightUpperArm.rotation.x = 0.2;
            leftLowerArm.rotation.x = -0.2;
            rightLowerArm.rotation.x = -0.2;

            groundSpeed = 0;

        } else if (phase === 'WALK') {
            // Walk Params
            legSpeed = 4.0; // Frequency
            legAmp = 0.5;   // Radians
            armAmp = 0.6;
            bodyLean = 0.05; // Slight forward
            bodyBob = 0.05;  // Vertical bounce
            groundSpeed = 0.5; // Speed of ground texture

            // Phase offset for walking (180 degrees between legs)
            const walkPhase = phaseTime * legSpeed;

            // Body
            hips.rotation.x = bodyLean;
            hips.position.y = 1.0 + Math.abs(Math.sin(walkPhase)) * bodyBob;

            // Legs (Sin wave)
            leftUpperLeg.rotation.x = Math.sin(walkPhase) * legAmp;
            rightUpperLeg.rotation.x = Math.sin(walkPhase + Math.PI) * legAmp;

            // Knee bend (Secondary rotation) - bend knee when leg goes back
            leftLowerLeg.rotation.x = Math.max(0, -Math.sin(walkPhase)) * 0.5;
            rightLowerLeg.rotation.x = Math.max(0, -Math.sin(walkPhase + Math.PI)) * 0.5;

            // Arms (Opposite to legs)
            leftUpperArm.rotation.x = Math.sin(walkPhase + Math.PI) * armAmp;
            rightUpperArm.rotation.x = Math.sin(walkPhase) * armAmp;

            // Elbow bend
            leftLowerArm.rotation.x = -0.5; // Constant slight bend
            rightLowerArm.rotation.x = -0.5;

        } else if (phase === 'RUN') {
            // Run Params
            legSpeed = 8.0; // Faster frequency
            legAmp = 1.2;   // Larger swing
            armAmp = 1.0;
            bodyLean = 0.3; // Significant forward lean
            bodyBob = 0.1;  // More bounce
            groundSpeed = 2.0; // Fast ground

            const runPhase = phaseTime * legSpeed;

            // Body
            hips.rotation.x = bodyLean;
            hips.position.y = 1.0 + Math.abs(Math.sin(runPhase)) * bodyBob;

            // Legs
            // Running involves lifting the heel (knee bend) significantly
            leftUpperLeg.rotation.x = Math.sin(runPhase) * legAmp;
            rightUpperLeg.rotation.x = Math.sin(runPhase + Math.PI) * legAmp;

            // Knee logic: Bend forward when swinging forward, extend back
            // Using a simple approach: bend based on sine
            leftLowerLeg.rotation.x = Math.max(0, Math.sin(runPhase)) * 1.5; 
            rightLowerLeg.rotation.x = Math.max(0, Math.sin(runPhase + Math.PI)) * 1.5;

            // Arms
            // Running arms swing more vertically and bend at elbow
            leftUpperArm.rotation.x = Math.sin(runPhase + Math.PI) * armAmp;
            rightUpperArm.rotation.x = Math.sin(runPhase) * armAmp;

            leftLowerArm.rotation.x = -1.5; // Bent elbow
            rightLowerArm.rotation.x = -1.5;
        }

        // Move Ground
        // We move the markings to simulate treadmill belt
        markingGroup.children.forEach(mark => {
            mark.position.z += groundSpeed * 0.05; // Scale speed for frame rate
            if (mark.position.z > 10) mark.position.z -= 20; // Loop markings
        });

        renderer.render(scene, camera);
    }

    // Handle Resize
    window.addEventListener('resize', () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    });

    // Start
    animate();

</script>
</body>
</html>
```
